from pathlib import Path
import re
live = Path(r"C:\Users\hzq00\Documents\Codex\2026-08-23\ni-j\work\stage2_continue\live")
seedp = Path(r"C:\Users\hzq00\Documents\Codex\2026-08-23\ni-j\work\stage2_pkg\HONOR_VER_AN10_CODEX_STAGE2_EXECUTION_PACKAGE\03_PACKAGE_POLICY_SEED.tsv")
policy = {}
for line in seedp.read_text(encoding="utf-8").splitlines()[1:]:
    if not line.strip():
        continue
    pkg, layer, pol, note = line.split("\t", 3)
    policy[pkg] = (layer, pol, note)

tp = {}
for line in (live/"third_party_user0.txt").read_text(encoding="utf-8").splitlines():
    if not line.startswith("package:"):
        continue
    rest = line[len("package:"):]
    pkg = rest.split()[0]
    inst = ""; uid = ""
    for tok in rest.split():
        if tok.startswith("installer="):
            inst = tok.split("=",1)[1]
        if tok.startswith("uid:"):
            uid = tok.split(":",1)[1]
    tp[pkg] = {"uid": uid, "installer": inst}

u128 = set()
for line in (live/"packages_user128.txt").read_text(encoding="utf-8").splitlines():
    if line.startswith("package:"):
        u128.add(line.split(":",1)[1].strip())

user_wl = {}
for line in (live/"whitelist.txt").read_text(encoding="utf-8").splitlines():
    line=line.strip()
    if line.startswith("user,"):
        _, pkg, uid = line.split(",", 2)
        user_wl[pkg] = uid

ime = (live/"ime.txt").read_text(encoding="utf-8").strip()
imes = (live/"imes.txt").read_text(encoding="utf-8").strip()
a11y = (live/"a11y.txt").read_text(encoding="utf-8").strip()
nls = (live/"nls.txt").read_text(encoding="utf-8").strip()
netpolicy = (live/"netpolicy.txt").read_text(encoding="utf-8").strip()
svc = (live/"activity_services.txt").read_text(encoding="utf-8", errors="replace")

special_pkgs = set()
for blob in (ime, imes, a11y, nls):
    for m in re.findall(r"([a-zA-Z0-9_.]+)/", blob):
        special_pkgs.add(m)
special_pkgs.update({"com.sohu.inputmethod.sogou","li.songe.gkd","cn.xiaolongonly.andpodsop","io.github.sds100.keymapper"})

hard_keep = {
    "com.tencent.mm","com.tencent.mobileqq","com.tencent.map","com.eg.android.AlipayGphone",
    "com.baidu.input_hihonor","fi.polar.polarflow","com.lerist.fakelocation"
} | special_pkgs

reduced = [k for k,v in policy.items() if v[1] in ("NMB_REDUCED","NMB_REDUCED_IF_IDLE") and k in tp]
print("IME", ime)
print("A11Y", a11y)
print("NLS", nls)
print("NETPOLICY", netpolicy)
print("special", sorted(special_pkgs))
print("third-party userWL", sorted(p for p in user_wl if p in tp))
print("reduced installed", len(reduced))

# FGS heuristic
fgs_hits = {}
for pkg in sorted(set(list(tp)+reduced)):
    if pkg in svc and ("Foreground" in svc[svc.find(pkg):svc.find(pkg)+800] or "isForeground=true" in svc[max(0,svc.find(pkg)-200):svc.find(pkg)+800]):
        fgs_hits[pkg] = True

print("possible FGS among candidates:")
for pkg in reduced:
    if pkg in fgs_hits:
        print(" FGS", pkg)

print("\nREDUCED PLAN")
for pkg in sorted(reduced):
    layer, pol, note = policy[pkg]
    wl = pkg in user_wl
    spec = pkg in special_pkgs
    keep = pkg in hard_keep
    fgs = pkg in fgs_hits
    ready = not (spec or keep or fgs)
    print(f"{'READY' if ready else 'SKIP ':5s} {pol:22s} wl={int(wl)} spec={int(spec)} fgs={int(fgs)} u128={int(pkg in u128)} {pkg}")
